//! Untagged original ordinary call-argument errors, over one evaluated walk.
//! Pinned visit_call: bad-keyword and positional-after-keyword only. Filter's
//! separate value-dependent rules are not inferred or claimed by this producer.
use crate::{checker_call_facts::CallableFact,checks::{Diagnostic,Note,Severity},checks_proc_visibility::{Findings,Row},checker_effects::{EffectReportWork,EffectTarget},policy_body_demand::PolicyFailure};
use dm_ir::{PackedU128,ProcedureIdentity,Resolver,SymbolId};use dm_tree::{frontend::{BodyArchive,ArchivedBody},MemberKind};use dm_syntax::{Expr,ExprKind,Span};use std::{borrow::Cow,fmt::{self,Write},io,mem::size_of};
fn oom()->PolicyFailure{PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"call-argument finding capacity overflow"))}
fn reserve<W:EffectReportWork>(work:&mut W,n:usize)->Result<(),PolicyFailure>{work.reserve(n).map_err(PolicyFailure::Operational)}
fn push<T,W:EffectReportWork>(work:&mut W,rows:&mut Vec<T>,value:T)->Result<(),PolicyFailure>{if rows.len()==rows.capacity(){let count=rows.capacity().checked_mul(2).and_then(|n|n.checked_add(1)).ok_or_else(oom)?;let bound=count.checked_mul(4).ok_or_else(oom)?;reserve(work,bound.checked_mul(size_of::<T>()).and_then(|n|n.checked_add(128)).ok_or_else(oom)?)?;rows.try_reserve_exact(count-rows.len()).map_err(|e|PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if rows.capacity()>bound{return Err(oom())}}rows.push(value);Ok(())}
struct Count(usize);impl Write for Count{fn write_str(&mut self,text:&str)->fmt::Result{self.0=self.0.checked_add(text.len()).ok_or(fmt::Error)?;Ok(())}}
struct Fixed<'a>(&'a mut String);impl Write for Fixed<'_>{fn write_str(&mut self,text:&str)->fmt::Result{if text.len()>self.0.capacity()-self.0.len(){return Err(fmt::Error)}self.0.push_str(text);Ok(())}}
fn text<W:EffectReportWork>(work:&mut W,args:fmt::Arguments<'_>)->Result<String,PolicyFailure>{let mut count=Count(0);count.write_fmt(args).map_err(|_|oom())?;let bound=count.0.checked_mul(4).ok_or_else(oom)?;reserve(work,bound.checked_add(size_of::<String>()+128).ok_or_else(oom)?)?;let mut out=String::new();out.try_reserve_exact(count.0).map_err(|e|PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if out.capacity()>bound{return Err(oom())}Fixed(&mut out).write_fmt(args).map_err(|_|oom())?;Ok(out)}
struct Arguments<'a,'w,W,R:?Sized>{resolver:&'w R,archive:&'a BodyArchive,profile:PackedU128,work:&'w mut W,checkpoint:&'w dyn Fn()->io::Result<()>,rows:Vec<Row>}
impl<'a,W:EffectReportWork,R:Resolver+?Sized> Arguments<'a,'_,W,R>{
 fn poll(&self)->Result<(),PolicyFailure>{(self.checkpoint)().map_err(PolicyFailure::Operational)}
 fn display(&mut self,target:EffectTarget)->Result<String,PolicyFailure>{let tree=self.archive.tree();match target{EffectTarget::Source(id)=>{let value=crate::checker_callable_display::original(tree,id,|_|Ok::<(),PolicyFailure>(()),||self.poll())?;text(self.work,format_args!("{value}"))},EffectTarget::Builtin(id)=>{let value=crate::checker_callable_display::builtin(tree,id,||self.poll())?;text(self.work,format_args!("{value}"))}}}
  fn key<'k>(&mut self,key:&'k Expr)->Result<Cow<'k,str>,PolicyFailure>{match &key.kind{ExprKind::Ident(name)=>Ok(Cow::Borrowed(name)),ExprKind::Literal(value)=>{let count=value.as_str().len();let max=count.checked_mul(4).ok_or_else(oom)?;reserve(self.work,max.checked_add(size_of::<String>()+128).ok_or_else(oom)?)?;let mut text=String::new();text.try_reserve_exact(count).map_err(|e|PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if text.capacity()>max{return Err(oom())}if !value.write_pinned_static_text(&mut Fixed(&mut text)).map_err(|e|format!("argument original key: {e:?}"))?{return Err("argument key is not original static text".into())}Ok(Cow::Owned(text))},_=>Err("argument key is outside the actual original key grammar".into())}}
 fn note(&mut self,source:crate::checker_effects::EffectTarget,current:Option<Span>,message:&str)->Result<Note,PolicyFailure>{self.poll()?;match source{EffectTarget::Source(id)=>{let member=self.archive.callables().members().iter().copied().find(|member|self.archive.callables().identity_for_member(*member)==Some(id)).ok_or("argument child original header absent")?;let headers=self.archive.callable_header_source();let point=headers.reported_point(member)?;let(path,_,_)=point.reported_coordinates();reserve(self.work,path.as_os_str().len().checked_mul(8).and_then(|n|n.checked_add(message.len().checked_mul(4)?)).and_then(|n|n.checked_add(size_of::<Note>()+512)).ok_or_else(oom)?)?;if let Some(current)=current{Ok(crate::checks_directive_binding::original_note_message(point,headers.reported_source_point(current.start)?,message))}else{let(path,line,column)=point.reported_coordinates();Ok(Note{message:text(self.work,format_args!("{}:{line}:{column}: {message}",path.display()))?,source:None})}},EffectTarget::Builtin(_)=>Ok(Note{message:text(self.work,format_args!("(builtins):1:1: {message}"))?,source:None})}}
 fn emit(&mut self,family:&'static str,at:Option<Span>,expression:Span,message:String,notes:Vec<Note>)->Result<(),PolicyFailure>{push(self.work,&mut self.rows,Row{diagnostic:Diagnostic{family,severity:Severity::Error,span:at.unwrap_or_default(),expression_span:expression,message,notes},synthetic:at.is_none()})}
}

impl<'a,W:EffectReportWork,R:Resolver+?Sized> Arguments<'a, '_,W,R>{
 fn spelling(&self,symbol:SymbolId,builtin:bool)->Result<&'a str,PolicyFailure>{if builtin{let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("argument catalog: {e:?}"))?;if catalog.profile!=self.profile{return Err("argument catalog profile differs".into())}catalog.spelling(symbol).ok_or_else(||"argument builtin spelling absent".into())}else{self.archive.tree().symbols().text(symbol).ok_or_else(||"argument source spelling absent".into())}}
 fn has_parameter(&self,fact:&CallableFact,key:&str)->Result<bool,PolicyFailure>{let tree=self.archive.tree();let target=crate::checker_effects::callable_target(tree,self.profile,fact)?;let builtin=matches!(target,EffectTarget::Builtin(_));let actual_name=match fact{CallableFact::Source{identity,..}=>identity.name,CallableFact::CheckerBuiltin{name,..}=>*name,CallableFact::Missing=>return Err("argument parameter target missing".into())};crate::checker_call_facts::require_original_group_chronology_using(tree,self.profile,fact,self.spelling(actual_name,builtin)?,&mut||self.poll())?;let signature=&fact.metadata().and_then(|m|m.procedure.as_ref()).ok_or("argument signature absent")?.signature;for parameter in signature.parameters.iter(){if self.spelling(parameter.name,builtin)?==key{return Ok(true)}}Ok(false)}
}

impl<W:EffectReportWork,R:Resolver+?Sized> crate::checker_expression_visit::ArgumentObserver<PolicyFailure> for Arguments<'_, '_,W,R>{fn begin_call(&mut self,tree:&dm_tree::SemanticTree,fact:&CallableFact,name:&str)->Result<(),PolicyFailure>{self.poll()?;if !std::ptr::eq(tree,self.archive.tree()){return Err("argument call tree differs from original archive".into())}crate::checker_call_facts::require_original_group_chronology_using(tree,self.profile,fact,name,&mut||self.poll())?;Ok(())}fn argument(&mut self,tree:&dm_tree::SemanticTree,fact:&CallableFact,name:&str,key:Option<&Expr>,after_keyword:bool,at:Option<Span>,expression:Span)->Result<(),PolicyFailure>{
 self.poll()?;if !std::ptr::eq(tree,self.archive.tree()){return Err("argument tree differs from original archive".into())}let target=crate::checker_effects::callable_target(tree,self.profile,fact)?;let owner=fact.owner().ok_or("argument callable owner absent")?;
 if let Some(key)=key{let key=self.key(key)?;if !self.has_parameter(fact,&key)?{let display=self.display(target)?;let message=text(self.work,format_args!("bad keyword argument {key:?} to {display}"))?;let mut candidates=Vec::<(&str,EffectTarget)>::new();let base=self.spelling(owner,matches!(target,EffectTarget::Builtin(_)))?;
 // Pinned recurse_children follows lexical PATH children, independently of
 // explicit parent_type. Keep only actual own latest callable declarations.
 for node in tree.types(){self.poll()?;let path=tree.symbols().text(node.path).ok_or("argument descendant path absent")?;if node.path==owner||!(base=="/"||path.strip_prefix(base).is_some_and(|suffix|suffix.starts_with('/'))){continue}let child=crate::checker_call_facts::callable_any_using(tree,self.resolver,self.profile,node.path,SymbolId::of(name),&mut||self.poll())?;if child.owner()!=Some(node.path){continue}if self.has_parameter(&child,&key)?{let child_target=crate::checker_effects::callable_target(tree,self.profile,&child)?;push(self.work,&mut candidates,(path,child_target))?;}}
 reserve(self.work,candidates.len().checked_mul(size_of::<(&str,EffectTarget)>()).and_then(|n|n.checked_add(128)).ok_or_else(oom)?)?;candidates.sort_by(|a,b|a.0.split('/').cmp(b.0.split('/')));let mut notes=Vec::new();for(_,child)in candidates{self.poll()?;let display=self.display(child)?;let note_message=text(self.work,format_args!("an override has this parameter: {display}"))?;let note=self.note(child,at,&note_message)?;push(self.work,&mut notes,note)?;}self.emit("bad_keyword_argument",at,expression,message,notes)?;}}
 if after_keyword&&!(owner==SymbolId::of("/")&&name=="animate"){let message=text(self.work,format_args!("proc called with non-kwargs after kwargs: {name}()"))?;self.emit("non_keyword_after_keyword",at,expression,message,Vec::new())?;}Ok(())
}}
/// Ordinary argument validation uses the SAME evaluated visitor and original
/// static-private argument abort. Findings remain borrowed from this archive.
pub fn with_archived_body<W:EffectReportWork,R:Resolver+?Sized>(archive:&BodyArchive,body:&ArchivedBody<'_>,resolver:&R,profile:PackedU128,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{checkpoint().map_err(PolicyFailure::Operational)?;if resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("argument resolver belongs to another archive".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|e|format!("argument profile: {e:?}"))?;let mut arguments=Arguments{archive,profile,work,checkpoint,resolver,rows:Vec::new()};let pending=(||{crate::checker_expression_visit::call_arguments_archived(archive,body,resolver,profile,checkpoint,&mut arguments)?;let findings=Findings::from_rows(archive,std::mem::take(&mut arguments.rows));checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)?;Ok(())})();if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending}
